'<div class="sh-pod-form-row"><span class="sh-pod-as"></span><span class="sh-pod-left" aria-live="polite"></span>' +
'<button type="submit" class="sh-pod-post">Post</button></div>' +
'<div class="sh-pod-formnote" role="status" hidden></div>' +
'</form></div>';
