try {
var bank = (typeof QUESTIONS !== "undefined") ? QUESTIONS : [];
var q = bank.filter(function(x){ return x.id === qid; })[0];
return q ? { text: (q.q || q.stem || null), lec: q.lec || null } : { text: null, lec: null };
} catch (e) { return { text: null, lec: null }; }
